import sys
sys.path.insert(0, '.')
from fetcher import fetch

class MockClient:
    def __init__(self):
        self.last_kwargs = None
    def get(self, url, timeout=None):
        self.last_kwargs = {'url': url, 'timeout': timeout}
        return f'response {url}'

def test_fetch_pass_timeout():
    client = MockClient()
    result = fetch(client, 'http://example.com')
    assert client.last_kwargs['timeout'] == 30
    assert result == 'response http://example.com'

def test_fetch_preserves_url():
    client = MockClient()
    result = fetch(client, 'http://test.com')
    assert client.last_kwargs['url'] == 'http://test.com'

if __name__ == '__main__':
    test_fetch_pass_timeout()
    test_fetch_preserves_url()
    print('All tests passed')

